    @Column(name = "proof_kinds")
    private String proofKinds;

    /** The default grade: the grade a person added by the quick-add bar, or by an import line with a blank
     *  grade, takes; none means A. Not dated. */
    @Column(name = "default_grade")
    private String defaultGrade;

    /** The retired grades, comma separated in the order retired: none can be chosen for a new person or in
     *  an edit from then on, though the people on one keep it; none means none. Not dated. */
    @Column(name = "retired_grades")
    private String retiredGrades;

    /** The month (1 to 12) a fiscal year starts in; a fiscal year is named by the calendar year its first
     *  day falls in. Not dated. */
    @Column(name = "fiscal_start_month", nullable = false)
    private int fiscalStartMonth = 1;

    /** The entry date: while set, the default date of a new claim in place of the sheet's today; none means
     *  off. Not dated. */
        this.proofKinds = proofKinds;
    }

    public String getDefaultGrade() {
        return defaultGrade;
    }

    /** The grade a new person takes when none is given: the default grade, or A when none is set or the
     *  default grade is retired. */
    public String defaultGradeOrA() {
        return defaultGrade == null || isGradeRetired(defaultGrade) ? "A" : defaultGrade;
    }

    /** The retired grades, in the order retired. */
    public List<String> getRetiredGrades() {
        return retiredGrades == null ? List.of() : Arrays.asList(retiredGrades.split(","));
    }

    public boolean isGradeRetired(String grade) {
        return getRetiredGrades().contains(grade);
    }

    /** Retire a grade not yet retired. */
    public void retireGrade(String grade) {
        retiredGrades = retiredGrades == null ? grade : retiredGrades + "," + grade;
    }

    public void setDefaultGrade(String defaultGrade) {
        this.defaultGrade = defaultGrade;
    }

    @Transactional
    public Sheet setReviewSla(String id, String user, Integer days) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        sheet.setReviewSla(days);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=review-sla value="
                + (days == null ? "" : days.toString()));
        return sheet;
    }

    /** Change the sheet's proof kinds (a comma separated list of receipt or photo; blank: none). Not dated. */
    @Transactional
    public Sheet setProofKinds(String id, String user, String kinds) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        String list = kinds == null ? "" : String.join(",", kinds.trim().split("\\s*,\\s*"));
        sheet.setProofKinds(list.isEmpty() ? null : list);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=proof-kinds value=" + list);
        return sheet;
    }

    /** Change the sheet's default grade (one of the grades; blank: A). Not dated; changes no one. */
    @Transactional
    public Sheet setDefaultGrade(String id, String user, String grade) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        String g = grade == null ? "" : grade.trim();
        sheet.setDefaultGrade(g.isEmpty() ? null : g);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=default-grade value=" + g);
        return sheet;
    }

    /** Retire a grade (one of the grades, not yet retired): it can no longer be chosen for a person, though
     *  the people on it keep it. Not dated. */
    @Transactional
    public Sheet retireGrade(String id, String user, String grade) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        String g = grade == null ? "" : grade.trim();
        if (!g.matches("[ABC]")) {
            throw new GradeRefusedException("Choose a grade of A, B or C.");
        }
        if (sheet.isGradeRetired(g)) {
            throw new GradeRefusedException("Grade " + g + " is already retired.");
        }
        sheet.retireGrade(g);
        audit.recordOnCommit("GRADE_RETIRED sheet=" + id + " by=" + user + " grade=" + g);
        return sheet;
    }

    /** Change the sheet's fiscal start month (1 to 12). Not dated. */
    @Transactional
    public Sheet setFiscalStartMonth(String id, String user, int month) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        sheet.setFiscalStartMonth(month);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=fiscal-start-month value=" + month);
        return sheet;
    }

    /** Change the sheet's pot (none: no pot). Not dated. */
    @Transactional
    public Sheet setPot(String id, String user, BigDecimal pot) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        Rollup.Snapshot before = rollup.take(id);
        BigDecimal p = pot == null ? null : pot.setScale(2);
        sheet.setPot(p);
        sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=pot value="
                + (p == null ? "" : p.toPlainString()));
        // a person's cut moves what the cap leaves their due-total
        rollup.recordChanges(id, user, before);
        return sheet;
    }

    /** Change the sheet's alert threshold (none: off). Not dated. */
    @Transactional
    public Sheet setAlertThreshold(String id, String user, BigDecimal threshold) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        BigDecimal t = threshold == null ? null : threshold.setScale(2);
        sheet.setAlertThreshold(t);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=alert-threshold value="
                + (t == null ? "" : t.toPlainString()));
        return sheet;
    }

