    public Sheet retireGrade(String id, String user, String grade) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        String g = grade == null ? "" : grade.trim();
        if (!g.matches("[ABC]")) {
